import { unstable_cache } from 'next/cache';
import fs from 'fs/promises';
import path from 'path';

// Using a file in the temporary directory to simulate a database
// In a real app, this would be a database connection
const DB_PATH = path.join(process.cwd(), 'posts.json');

export type Post = {
  id: string;
  title: string;
  content: string;
  createdAt: string;
};

async function getPostsHandler() {
  try {
    const data = await fs.readFile(DB_PATH, 'utf-8');
    return JSON.parse(data) as Post[];
  } catch (error) {
    // If file doesn't exist, return empty array
    return [];
  }
}

// Cached version of getPosts using Next.js cache tags
export const getPosts = unstable_cache(
  getPostsHandler,
  ['posts-cache-key'], // Internal cache key
  { tags: ['posts'] } // The tag we will invalidate
);

export async function addPost(title: string, content: string) {
  const posts = await getPostsHandler(); // Get fresh data directly, bypassing cache for writing

  const newPost: Post = {
    id: Date.now().toString(),
    title,
    content,
    createdAt: new Date().toISOString(),
  };

  const updatedPosts = [newPost, ...posts];
  await fs.writeFile(DB_PATH, JSON.stringify(updatedPosts, null, 2));

  return newPost;
}

