'use server';

import { revalidateTag } from 'next/cache';
import { addPost } from './lib/data';

export async function createPost(formData: FormData) {
  const title = formData.get('title');
  const content = formData.get('content');

  if (!title || typeof title !== 'string' || !content || typeof content !== 'string') {
    return { error: 'Invalid title or content' };
  }

  // Create the post
  await addPost(title, content);

  // Invalidate the cache for the 'posts' tag
  // This ensures that any component using unstable_cache with this tag (like getPosts)
  // will be re-executed on the next request, guaranteeing fresh data.
  revalidateTag('posts');

  return { success: true };
}

